66:/**
67: * Read the posting id out of an apply URL, or null when the URL does not carry
68: * one.
69: *
70: * Null is the common case and must stay cheap: a company career page, a
71: * redirect through a tracker, a multi-step form with a session token. Those are
72: * compared by nothing, which is correct — this only ever answers "these two
73: * URLs name DIFFERENT postings", never "these are the same one".
74: */
75:export function postingIdentity(
76:  url: string | null | undefined,
77:): PostingIdentity | null {
78:  if (!url) return null;
79:  let u: URL;
80:  try {
81:    u = new URL(url.trim());
82:  } catch {
83:    return null;
84:  }
